sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
     var defvalue = 'Consultant,Associate,Senior Consultant,Lead Consultant,Junior Lead Consultant,Senior Lead Consultant';
    if (event.payload.value.toString() == '') {

        api.setState('posFilterParam', "Consultant,Associate,Senior Consultant,Lead Consultant,Junior Lead Consultant,Senior Lead Consultant");
        api.data.resource_profile_table.refresh();
    } else {

        api.setState('posFilterParam', event.payload.value);
        api.data.resource_profile_table.refresh();
    }

}
